<?php require '../includes/app.php';admin();require 'layout.php';$s=settings();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check();$values=[];foreach($s as $key=>$old){$v=trim($_POST[$key]??'');if(strlen($v)>10000)$error='A field is too long.';$values[$key]=$v;}if(empty($values['company_name']))$error='Company name is required.';if($values['email']&&!filter_var($values['email'],FILTER_VALIDATE_EMAIL))$error='Invalid public email.';if(!$error){db()->beginTransaction();$q=db()->prepare('UPDATE settings SET value=? WHERE name=?');foreach($values as $key=>$v)$q->execute([$v,$key]);db()->commit();header('Location: settings.php?saved=1');exit;}}top('Company settings');if(isset($_GET['saved']))echo '<p>Saved.</p>';echo '<p>'.e($error).'</p>';?><form method="post"><?=token()?><?php foreach($s as $key=>$value):?><label><?=e(ucwords(str_replace('_',' ',$key)))?><textarea name="<?=e($key)?>"><?=e($_POST[$key]??$value)?></textarea></label><?php endforeach;?><button class="btn-company">Save settings</button></form><?php bottom();?>